sp_widget.script:
(function() {
			function formatISODate(isoDateStr) {
					// Erstellen eines Date-Objekts aus dem ISO-Datumstring
					const date = new Date(isoDateStr);

					// Extrahieren der einzelnen Komponenten
					const day = String(date.getUTCDate()).padStart(2, '0');
					const month = String(date.getUTCMonth() + 1).padStart(2, '0'); // Monate sind 0-basiert
					const year = date.getUTCFullYear();

					const hours = String(date.getUTCHours()).padStart(2, '0');
					const minutes = String(date.getUTCMinutes()).padStart(2, '0');

					// Zusammenfügen in das gewünschte Format
					return `${day}.${month}.${year} ${hours}:${minutes}`;
			}
			if(!input){
				data.requestedItems = [];
				var gr = new GlideRecord('sc_req_item');
				gr.addQuery('state', '=', 1);
				gr.orderByDesc('sys_created_on');
				gr.query();

				 while (gr.next()) {
						data.requestedItems.push({
							sys_id: gr.getValue('sys_id'),
							number: gr.getValue('number'),
							short_description: gr.getValue('short_description')
						});
				 }
			}

			if (input) {
				data.result = [];
        // Übermittelte POST-Daten verarbeiten
        if (input.action === 'saveDeliveryDates') {
						console.log(input.requestedItem.sys_id);
						input.deliveryDates.forEach(function(deliveryDate) {
								var suggestedDeliveryDate = formatISODate(deliveryDate);
								var ritmGR = new GlideRecord('sc_req_item');
								if (ritmGR.get(input.requestedItem.sys_id)) {
									var taskGR = new GlideRecord('sc_task');
									taskGR.initialize();
									taskGR.short_description = 'Lieferterminvorschlag';
									taskGR.request_item = ritmGR.sys_id; // Verknüpfung mit dem Requested Item
									taskGR.assignment_group = ''; // Optional: Gruppe zuweisen
									taskGR.state = -5; // Status Offen
									taskGR.expected_start = suggestedDeliveryDate; // Termin setzen
									taskGR.insert();
								}
						});
    		}
			}
})();
